"""Synchronous Strata client — wraps AsyncStrataClient for non-async usage."""

from __future__ import annotations

import asyncio
import threading
from typing import Any

from strata.async_client import AsyncStrataClient
from strata.transport.base import Transport
from strata.types import (
    HistoryEvent,
    IngestResult,
    Memory,
    Project,
    SearchResult,
)


class StrataClient:
    """Synchronous client for Strata memory operations.

    Usage::

        s = StrataClient()
        results = s.search("auth patterns")

        # Or as context manager:
        with StrataClient() as s:
            results = s.search("auth patterns")
    """

    def __init__(
        self,
        url: str | None = None,
        token: str | None = None,
        transport: Transport | None = None,
        user: str | None = None,
    ) -> None:
        self._async_client = AsyncStrataClient(
            url=url, token=token, transport=transport, user=user
        )
        self._loop: asyncio.AbstractEventLoop | None = None
        self._thread: threading.Thread | None = None

    def _get_loop(self) -> asyncio.AbstractEventLoop:
        """Get or create a dedicated event loop running in a background thread.

        This avoids conflicts with existing event loops (Jupyter, FastAPI).
        """
        if self._loop is not None and self._loop.is_running():
            return self._loop

        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(
            target=self._loop.run_forever, daemon=True, name="strata-event-loop"
        )
        self._thread.start()
        return self._loop

    def _run(self, coro: Any) -> Any:
        """Run an async coroutine synchronously.

        Uses asyncio.run() when no event loop is running,
        otherwise delegates to a background thread loop.
        """
        try:
            asyncio.get_running_loop()
            # There's already an event loop — use background thread
            loop = self._get_loop()
            future = asyncio.run_coroutine_threadsafe(coro, loop)
            return future.result()
        except RuntimeError:
            # No running event loop — safe to use asyncio.run()
            return asyncio.run(coro)

    def connect(self) -> None:
        """Connect to the Strata MCP server."""
        self._run(self._async_client.connect())

    def close(self) -> None:
        """Close the connection and clean up resources."""
        self._run(self._async_client.close())
        if self._loop is not None:
            self._loop.call_soon_threadsafe(self._loop.stop)
            if self._thread is not None:
                self._thread.join(timeout=5)
            self._loop.close()
            self._loop = None
            self._thread = None

    def __enter__(self) -> StrataClient:
        self.connect()
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    # ── Core CRUD (Mem0-compatible surface) ──────────────────────────

    def add(
        self,
        text: str,
        *,
        type: str = "learning",
        tags: list[str] | None = None,
        project: str | None = None,
        user: str | None = None,
        user_id: str | None = None,
    ) -> Memory:
        """Store a memory. Returns the created Memory object."""
        return self._run(
            self._async_client.add(
                text, type=type, tags=tags, project=project, user=user, user_id=user_id
            )
        )

    def search(
        self,
        query: str,
        *,
        limit: int = 20,
        project: str | None = None,
        user: str | None = None,
        user_id: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Search memories. Returns a list of SearchResult objects."""
        return self._run(
            self._async_client.search(
                query, limit=limit, project=project, user=user, user_id=user_id, format=format
            )
        )

    def update(
        self,
        id: str,
        *,
        summary: str | None = None,
        tags: list[str] | None = None,
        user: str | None = None,
        user_id: str | None = None,
    ) -> Memory:
        """Update a memory entry."""
        return self._run(
            self._async_client.update(
                id, summary=summary, tags=tags, user=user, user_id=user_id
            )
        )

    def delete(self, id: str) -> bool:
        """Delete a memory entry. Returns True if deleted."""
        return self._run(self._async_client.delete(id))

    def history(self, id: str) -> list[HistoryEvent]:
        """Get the history of a memory entry."""
        return self._run(self._async_client.history(id))

    # ── Strata-specific tools (beyond Mem0) ──────────────────────────

    def find_solutions(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Search for solutions to errors or problems."""
        return self._run(
            self._async_client.find_solutions(query, limit=limit, project=project, format=format)
        )

    def find_patterns(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
        format: str = "detailed",
    ) -> list[SearchResult]:
        """Discover recurring patterns."""
        return self._run(
            self._async_client.find_patterns(query, limit=limit, project=project, format=format)
        )

    def find_procedures(
        self,
        query: str,
        *,
        limit: int = 10,
        project: str | None = None,
    ) -> list[SearchResult]:
        """Find step-by-step procedures."""
        return self._run(
            self._async_client.find_procedures(query, limit=limit, project=project)
        )

    def ingest(
        self,
        messages: list[dict[str, str]],
        *,
        agent: str = "custom-agent",
        project: str | None = None,
    ) -> IngestResult:
        """Ingest a full conversation through the extraction pipeline."""
        return self._run(
            self._async_client.ingest(messages, agent=agent, project=project)
        )

    def search_entities(
        self,
        query: str,
        *,
        limit: int = 10,
        type: str | None = None,
        project: str | None = None,
    ) -> list[SearchResult]:
        """Search the entity graph."""
        return self._run(
            self._async_client.search_entities(query, limit=limit, type=type, project=project)
        )

    def store_procedure(
        self,
        title: str,
        steps: list[str],
        *,
        project: str | None = None,
        tags: list[str] | None = None,
    ) -> Memory:
        """Store an explicit procedure."""
        return self._run(
            self._async_client.store_procedure(title, steps, project=project, tags=tags)
        )

    def get_project_context(self, project: str) -> str:
        """Get comprehensive context for a project."""
        return self._run(self._async_client.get_project_context(project))

    def list_projects(self, *, format: str = "detailed") -> list[Project]:
        """List all indexed projects."""
        return self._run(self._async_client.list_projects(format=format))

    @classmethod
    def from_env(cls) -> StrataClient:
        """Create a client configured from environment variables."""
        import os

        return cls(
            url=os.environ.get("STRATA_URL"),
            token=os.environ.get("STRATA_TOKEN"),
        )
